Python uses try/except blocks to handle exceptions:

```python
try:
    result = 10 / 0
except ZeroDivisionError as e:
    print(f'Error: {e}')

# Multiple exception types
try:
    value = int(input('Enter a number: '))
    result = 100 / value
except ValueError:
    print('Not a valid number')
except ZeroDivisionError:
    print('Cannot divide by zero')
except Exception as e:
    print(f'Unexpected error: {e}')
else:
    print(f'Result: {result}')  # runs if no exception
finally:
    print('This always runs')   # cleanup code
```

Best practices: catch specific exceptions (not bare `except:`), use `finally` for cleanup (closing files, DB connections), and don't silently swallow exceptions.

```python
class BankAccount:
    def __init__(self, owner: str, initial_balance: float = 0.0):
        self.owner = owner
        self._balance = initial_balance

    def deposit(self, amount: float) -> float:
        if amount <= 0:
            raise ValueError('Deposit amount must be positive')
        self._balance += amount
        return self._balance

    def withdraw(self, amount: float) -> float:
        if amount <= 0:
            raise ValueError('Withdrawal amount must be positive')
        if amount > self._balance:
            raise ValueError('Insufficient funds')
        self._balance -= amount
        return self._balance

    @property
    def balance(self) -> float:
        return self._balance

    def __repr__(self) -> str:
        return f'BankAccount(owner={self.owner!r}, balance={self._balance:.2f})'


account = BankAccount('Alice', 100.0)
account.deposit(50)    # balance = 150.0
account.withdraw(30)   # balance = 120.0
print(account.balance) # 120.0
```
